const allNewPages = [...pagesData, ...remainingHadiths];

function formatPage(item) {
  let content = `بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ\n`;
  content += `«المسند للإمام أحمد بن حنبل» — ${item.chAr}\n`;
  content += `[صَفْحَة ${item.pageNum} • ${item.chUr}]\n\n`;

  content += `【متنِ کتاب (عربی)】\n`;
  content += `${item.matn}\n\n`;

  content += `【سلیس اردو ترجمہ و درسی حل】\n`;
  content += `سلیس اردو ترجمہ:\n${item.urdu}\n\n`;

  content += `درسی تشریح و حل:\n${item.tashreeh}\n\n`;

  if (item.iraab && item.iraab.length > 0) {
    const iraabLines = item.iraab.map(m => `• [${m.word}]: ${m.role} (${m.sign}) — ${m.detail}`).join('\n');
    content += `محلِ اعراب و نحوی ترکیب:\n${iraabLines}\n\n`;
  }

  if (item.hawashi && item.hawashi.length > 0) {
    const hawashiLines = item.hawashi.map(h => `• ${h}`).join('\n');
    content += `حواشی و درسی فوائد:\n${hawashiLines}\n\n`;
  }

  content += `【حوالہ و تصدیقِ ماخذ】\n`;
  content += `مأخوذ از مصدقہ نسخہ • وقفِ عام (جلد: ${item.vol || 50}، صفحہ: ${item.pageNum}).\n`;
  content += `----------------------------------------`;

  return content.trim();
}

console.log(`Generating ${allNewPages.length} new pages (525 to 574)...`);
const existingChunk5 = JSON.parse(fs.readFileSync(chunk5Path, 'utf8'));
console.log(`Existing chunk 5 pages count: ${existingChunk5.length}`);

for (const p of allNewPages) {
  const formatted = formatPage(p);
  existingChunk5.push(formatted);
}

console.log(`New chunk 5 pages count: ${existingChunk5.length}`);
fs.writeFileSync(chunk5Path, JSON.stringify(existingChunk5, null, 2), 'utf8');
console.log(`Successfully updated ${chunk5Path}`);

